// ---- Vapi tool-call parsing (defensive) --------------------------------
// Vapi POSTs { message: { type:'tool-calls', toolCallList:[{id,name,arguments}], call:{...} } }
// n8n nests the HTTP body under $json.body. `arguments` sometimes arrives as a
// JSON *string* rather than an object, so parse it defensively.
function parseVapi(item) {
  const body = item.body || item;
  const msg = body.message || {};
  const list = msg.toolCallList || msg.toolCalls || [];
  const tc = list[0] || {};
  let args = tc.arguments ?? tc.function?.arguments ?? {};
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  const callerNumber = msg.call?.customer?.number || null;
  return {
    toolCallId: tc.id || tc.toolCallId || 'unknown',
    name: tc.name || tc.function?.name || '',
    args: args || {},
    callerNumber,
    callId: msg.call?.id || null,
  };
}

// ---- Phone normalisation (mirrors lib/squeegee/sms.ts) -----------------
function normalizePhone(raw) {
  const digits = String(raw ?? '').replace(/[^0-9]/g, '');
  const ten = digits.length === 11 && digits.startsWith('1') ? digits.slice(1) : digits;
  if (ten.length !== 10) return null;
  return { phone10: ten, e164: '+1' + ten };
}

// ---- Spoken-form money -------------------------------------------------
// TTS reads "$475" inconsistently; spelling it out is the documented fix.
const ONES = ['zero','one','two','three','four','five','six','seven','eight','nine','ten',
  'eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
const TENS = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
function under1000(n) {
  let out = [];
  if (n >= 100) { out.push(ONES[Math.floor(n / 100)] + ' hundred'); n %= 100; }
  if (n >= 20) { out.push(TENS[Math.floor(n / 10)] + (n % 10 ? '-' + ONES[n % 10] : '')); }
  else if (n > 0) { out.push(ONES[n]); }
  return out.join(' ');
}
function spellDollars(amount) {
  const n = Math.round(Number(amount) || 0);
  if (n === 0) return 'zero dollars';
  const th = Math.floor(n / 1000), rest = n % 1000;
  let s = '';
  if (th) s += under1000(th) + ' thousand' + (rest ? ' ' : '');
  if (rest) s += under1000(rest);
  return s + ' dollars';
}

// ---- Spoken-form date/time (America/New_York) --------------------------
function spokenSlot(iso) {
  const d = new Date(iso);
  const day = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'long', day: 'numeric' }).format(d);
  const hourFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', hour12: true }).format(d);
  let [clock, ampm] = hourFmt.split(' ');
  let [h, m] = clock.split(':');
  const timePart = m === '00' ? h : h + ' ' + m;
  const hh = Number(h);
  // 12 PM..4:59 PM = afternoon, 5 PM+ = evening (noon used to fall into 'evening').
  const partOfDay = ampm === 'AM' ? 'in the morning' : ((hh === 12 || hh < 5) ? 'in the afternoon' : 'in the evening');
  return day + ' at ' + timePart + ' ' + partOfDay;
}

// ---- DST-correct Eastern ISO (mirrors lib/squeegee/calcom.ts) ----------
function easternOffsetFor(dateStr) {
  try {
    const dt = new Date(dateStr + 'T12:00:00Z');
    const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', timeZoneName: 'longOffset' }).formatToParts(dt);
    const tz = parts.find(p => p.type === 'timeZoneName')?.value;
    const m = tz && tz.match(/GMT([+-]\d{2}:\d{2})/);
    return m ? m[1] : '-05:00';
  } catch (e) { return '-05:00'; }
}

// ---- Always-200 Vapi envelope -----------------------------------------
function vapiResult(toolCallId, text) {
  return [{ json: { results: [{ toolCallId, result: text }] } }];
}

// CONTRACT: `capture_lead` tool -> callerName, phoneNumber, email?, address?,
//   servicesRequested[], reason (enum), notes?, smsConsent?, callbackRequested?
// squeegee_leads has no `reason`/`notes` column, so the full context is ALSO
// written to squeegee_activity (job_id NULL) and pushed to Slack + owner SMS —
// nothing the caller said is lost. See README for the optional migration that
// would give squeegee_leads first-class columns for these.
const v = parseVapi($input.first().json);
const a = v.args || {};
const norm = normalizePhone(a.phoneNumber || a.phone || v.callerNumber);

let services = a.servicesRequested ?? a.services ?? [];
if (typeof services === 'string') services = [services];
if (!Array.isArray(services) || services.length === 0) services = ['general enquiry'];

const consent = a.smsConsent === true || a.smsConsent === 'true';
const reason = String(a.reason || 'other');
const notes = String(a.notes || a.summary || '').trim();
const callback = a.callbackRequested === true || a.callbackRequested === 'true';


// ---- one-parameter transport for Postgres writes ----------------------------
// The Postgres node splits its Query Parameters string on commas AFTER resolving
// expressions (observed live 2026-09-08), so a comma in an address shifts every
// bind parameter. Base64 has no commas: ship one encoded JSON document and unpack
// it in SQL with convert_from(decode($1,'base64'),'UTF8')::jsonb.
function toB64(str) {
  if (typeof Buffer !== 'undefined') return Buffer.from(str, 'utf8').toString('base64');
  return btoa(unescape(encodeURIComponent(str)));
}

const context = [
  'Reason: ' + reason,
  notes ? 'Notes: ' + notes : null,
  callback ? 'Caller asked for a callback.' : null,
  'Captured by the after-hours voice agent' + (v.callId ? ' (call ' + v.callId + ')' : '') + '.',
].filter(Boolean).join(' ');

return [{ json: {
  ...v,
  name: String(a.callerName || a.name || 'Unknown caller').trim(),
  phone: norm ? norm.e164 : null,
  phone10: norm ? norm.phone10 : null,
  email: a.email ? String(a.email).trim() : '',
  address: a.address ? String(a.address).trim() : '',
  servicesText: services.join(', '),
  propertyType: a.propertyType || '',
  timeline: a.timeline || '',
  reason,
  notes,
  callbackRequested: callback,
  context,
  smsConsent: consent,
  consentAt: consent ? new Date().toISOString() : '',
  hasPhone: !!(norm && norm.phone10),
  leadPayloadB64: toB64(JSON.stringify({
    name: String(a.callerName || a.name || 'Unknown caller').trim(),
    phone: norm ? norm.e164 : null,
    email: a.email ? String(a.email).trim() : '',
    address: a.address ? String(a.address).trim() : '',
    services,
    property_type: a.propertyType || '',
    timeline: a.timeline || '',
    sms_consent: consent,
    consent_at: consent ? new Date().toISOString() : '',
  })),
  // one pre-built string for the squeegee_activity note: n8n >= 2.5 turns every {{ }} in
  // Query Parameters into its own bind parameter, so the note must be a single expression.
  leadNoteB64: toB64(String(a.callerName || a.name || 'Unknown caller').trim() + ' — ' + (norm ? norm.e164 : 'no number') + ' — ' +
    services.join(', ') + '. ' + context),
} }];

