const ctx = $('Parse Lead').first().json;
const row = $input.first().json || {};
if (!ctx.hasPhone) {
  return vapiResult(ctx.toolCallId,
    'I still need a good callback number before I can pass this to Anthony. Ask for it, then call this again.');
}
if (!row || !row.id) {
  return vapiResult(ctx.toolCallId,
    'Details noted and Anthony has been alerted directly. Tell the caller he will be in touch shortly.');
}
return vapiResult(ctx.toolCallId,
  'Got it — details saved and Anthony has been texted. Tell the caller he will follow up personally, and thank them for calling.');
